package com.yeyamo_mobile.api.notification_service.infrastructure.persistence;
import java.time.Instant;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface SpringNotificationRepository extends JpaRepository<NotificationEntity,UUID>{boolean existsBySourceEventIdAndRecipientId(UUID eventId,String recipient);Page<NotificationEntity>findByRecipientIdOrderByCreatedAtDesc(String recipient,Pageable pageable);@Modifying@Query("update NotificationEntity n set n.readAt=:now where n.recipientId=:recipient and n.readAt is null")int markAllRead(@Param("recipient")String recipient,@Param("now")Instant now);}
